package com.csust.eyediagnosis.workflow.persistence.repository;
import com.baomidou.mybatisplus.core.conditions.update.LambdaUpdateWrapper; import com.csust.eyediagnosis.workflow.persistence.entity.DiagnosisWorkflowEntity; import com.csust.eyediagnosis.workflow.persistence.mapper.DiagnosisWorkflowMapper; import org.springframework.stereotype.Repository; import java.time.LocalDateTime; import java.util.Optional;
@Repository public class MybatisDiagnosisWorkflowRepository implements DiagnosisWorkflowRepository { private final DiagnosisWorkflowMapper mapper; public MybatisDiagnosisWorkflowRepository(DiagnosisWorkflowMapper mapper){this.mapper=mapper;} public Optional<DiagnosisWorkflowEntity> findByWorkflowId(String id){return Optional.ofNullable(mapper.selectById(id));} public Optional<DiagnosisWorkflowEntity> findByOwnerAndIdempotencyKey(Long owner,String key){return Optional.ofNullable(mapper.selectOne(new com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper<DiagnosisWorkflowEntity>().eq(DiagnosisWorkflowEntity::getOwnerUserId,owner).eq(DiagnosisWorkflowEntity::getCreationIdempotencyKey,key)));} public int insert(DiagnosisWorkflowEntity e){return mapper.insert(e);} public int updateStateIfVersionMatches(String id,long version,String expected,String target,String segment,String publication,String exposure,String stop,String limitation){return mapper.update(null,new LambdaUpdateWrapper<DiagnosisWorkflowEntity>().eq(DiagnosisWorkflowEntity::getWorkflowId,id).eq(DiagnosisWorkflowEntity::getWorkflowVersion,version).eq(DiagnosisWorkflowEntity::getStatus,expected).set(DiagnosisWorkflowEntity::getStatus,target).set(DiagnosisWorkflowEntity::getCurrentSegmentCode,segment).set(DiagnosisWorkflowEntity::getExplanationPublicationStatus,publication).set(DiagnosisWorkflowEntity::getPredictionExposureStatus,exposure).set(DiagnosisWorkflowEntity::getStopReasonCode,stop).set(DiagnosisWorkflowEntity::getLimitationReasonCode,limitation).set(DiagnosisWorkflowEntity::getUpdatedAt,LocalDateTime.now()).setSql("workflowVersion = workflowVersion + 1"));} }
